    function offsetMenuTowardViewer(anchorPosition, distance = 0.065) {
        try {
            if (!headCollider || headCollider.isNull?.()) return anchorPosition;
            const anchor = readVec3Components(anchorPosition);
            const viewer = readVec3Components(getTransform(headCollider).method("get_position").invoke());
            const dx = viewer[0] - anchor[0];
            const dy = viewer[1] - anchor[1];
            const dz = viewer[2] - anchor[2];
            const magnitude = Math.sqrt(dx * dx + dy * dy + dz * dz);
            if (!Number.isFinite(magnitude) || magnitude < 0.001) return anchorPosition;
            const amount = Math.min(Math.max(distance, 0), magnitude * 0.35);
            return [
                anchor[0] + (dx / magnitude) * amount,
                anchor[1] + (dy / magnitude) * amount,
                anchor[2] + (dz / magnitude) * amount
            ];
        } catch (_) { return anchorPosition; }
    }
    function recenterMenu() {
        const menuTransform = getTransform(menu);
        let targetPos, targetRot;
        // Flatscreen: anchor the menu in front of the camera. Its interactive face is local +X, so
        // LookRotation(cameraRight, cameraUp) makes +X point back at the camera (buttons face you) with
        // the button grid spread across screen-right (local Z) and screen-up (local Y). VR falls through
        // to the hand-follow anchor below.
        if (pcModeEnabled && flatscreenActive) {
            try {
                const cam = pcMainCamera();
                if (cam) {
                    const ct = cam.method("get_transform").invoke();
                    const cp = ct.method("get_position").invoke();
                    const cf = ct.method("get_forward").invoke();
                    const cr = ct.method("get_right").invoke();
                    const cu = ct.method("get_up").invoke();
                    targetPos = [
                        cp.field("x").value + cf.field("x").value * pcMenuDistance,
                        cp.field("y").value + cf.field("y").value * pcMenuDistance,
                        cp.field("z").value + cf.field("z").value * pcMenuDistance
                    ];
                    // The button list runs down the menu's local +Z and the face normal is local +X. To
                    // stand it upright and facing you: local +Z must map to world up (list vertical) and
                    // local +X to -cameraForward (face toward camera). LookRotation(forward=camUp,
                    // upHint=-cameraRight) yields exactly that. (The old LookRotation(camRight,camUp) put
                    // the list along camera-right, which is why it looked sideways.)
                    const negRight = Vector3.method("op_Multiply", 2).invoke(cr, -1.0);
                    targetRot = Quaternion.method("LookRotation", 2).invoke(cu, negRight);
                    if (menuSnapNextFrame) {
                        menuTransform.method("set_position").invoke(targetPos);
                        menuTransform.method("set_rotation").invoke(targetRot);
                        menuSnapNextFrame = false;
                    } else {
                        const menuPos = menuTransform.method("get_position").invoke();
                        menuTransform.method("set_position").invoke(Vector3.method("Lerp").invoke(menuPos, targetPos, Math.min(1.0, deltaTime * 18)));
                        menuTransform.method("set_rotation").invoke(Quaternion.method("Slerp").invoke(menuTransform.method("get_rotation").invoke(), targetRot, Math.min(1.0, deltaTime * 18)));
                    }
                    return;
                }
            } catch (_) { }
        }
        // When search keyboard is open, float menu in front of the player's face like Seralyth
        if (currentCategory === 20 && headCollider && !headCollider.isNull?.()) {
            try {
                const headTf = getTransform(headCollider);
                const headPos = headTf.method("get_position").invoke();
                const headFwd = headTf.method("get_forward").invoke();
                const headRot = headTf.method("get_rotation").invoke();
                // Position 0.65 units in front of head, slightly below eye level
                const tx = headPos.field("x").value + headFwd.field("x").value * 0.65;
                const ty = headPos.field("y").value - 0.08;
                const tz = headPos.field("z").value + headFwd.field("z").value * 0.65;
                const floatPos = Vector3.alloc();
                floatPos.method(".ctor").overload("System.Single", "System.Single", "System.Single").invoke(tx, ty, tz);
                // Face the player — yaw only so it stays upright
                const fwdX = headFwd.field("x").value;
                const fwdZ = headFwd.field("z").value;
                const yaw = Math.atan2(fwdX, fwdZ) * (180 / Math.PI);
                const facingRot = Quaternion.method("Euler").invoke(0, yaw + 180, 0);
                if (menuSnapNextFrame) {
                    menuTransform.method("set_position").invoke(floatPos);
                    menuTransform.method("set_rotation").invoke(facingRot);
                    menuSnapNextFrame = false;
                }
                else {
                    const menuPos = menuTransform.method("get_position").invoke();
                    menuTransform.method("set_position").invoke(Vector3.method("Lerp").invoke(menuPos, floatPos, Math.min(1.0, deltaTime * 8)));
                    menuTransform.method("set_rotation").invoke(Quaternion.method("Slerp").invoke(menuTransform.method("get_rotation").invoke(), facingRot, Math.min(1.0, deltaTime * 8)));
                }
                return;
            }
            catch (_) { }
        }
        // Default — follow hand
        if (righthand) {
            targetPos = offsetMenuTowardViewer(rightHandTransform.method("get_position").invoke());
            targetRot = rightHandTransform.method("get_rotation").invoke();
            targetRot = Quaternion.method("op_Multiply").invoke(targetRot, Quaternion.method("Euler").invoke(0, 0, 180));
        }
        else {
            targetPos = offsetMenuTowardViewer(leftHandTransform.method("get_position").invoke());
            targetRot = leftHandTransform.method("get_rotation").invoke();
        }
        if (menuSnapNextFrame) {
            menuTransform.method("set_position").invoke(targetPos);
            menuTransform.method("set_rotation").invoke(targetRot);
            menuSnapNextFrame = false;
        }
        else if (LerpMenu || true) {
            const menuPos = menuTransform.method("get_position").invoke();
            menuTransform.method("set_position").invoke(Vector3.method("Lerp").invoke(menuPos, targetPos, Math.min(1.0, deltaTime * 22)));
            menuTransform.method("set_rotation").invoke(Quaternion.method("Slerp").invoke(menuTransform.method("get_rotation").invoke(), targetRot, Math.min(1.0, deltaTime * 20)));
        }
        else {
            menuTransform.method("set_position").invoke(targetPos);
            menuTransform.method("set_rotation").invoke(targetRot);
        }
    }
