            const items = Object.method("FindObjectsByType", 1).inflate(GBIClass).invoke(0);
            if (items && !items.isNull()) {
                for (let i = 0; i < items.length; i++) {
                    try {
                        const item = items.get(i);
                        if (!item || item.isNull?.())
                            continue;
                        pushItem(item);
                    }
                    catch (_) { }
                }
            }
