    function getRunnerCandidates() {
        const results = [];
        const seen = new Set();
        const pushRunner = (runner) => {
            try {
                if (!runner || runner.isNull?.())
                    return;
                const key = normalizeSceneObjectHandle(runner) || String(runner);
                if (seen.has(key))
                    return;
                seen.add(key);
                results.push(runner);
            }
            catch (_) { }
        };
        try {
            const sfx = SFXManager.field("_instance").value;
            if (sfx && !sfx.isNull?.()) {
                try {
                    pushRunner(sfx.method("get__currentRunner").invoke());
                }
                catch (_) { }
                try {
                    pushRunner(sfx.field("_currentRunner").value);
                }
                catch (_) { }
            }
        }
        catch (_) { }
        try {
            const pgInst = PrefabGen.field("_instance").value;
            if (pgInst && !pgInst.isNull?.()) {
                try {
                    pushRunner(pgInst.method("get_runner").invoke());
                }
                catch (_) { }
            }
        }
        catch (_) { }
        try {
            const nm = NManager.field("<Instance>k__BackingField").value;
            if (nm && !nm.isNull?.()) {
                try {
                    pushRunner(nm.method("get_runner").invoke());
                }
                catch (_) { }
            }
        }
        catch (_) { }
        return results;
    }
