    let buttonMap = new Map();
    // All keyboard keys for the VR search keyboard
    const KB_ROWS = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
    const KB_SPECIALS = ["SK_back", "SK_clear", "SK_space", "SK_exit"];
    function getSearchResults() {
        if (hellOreMode) return [];
        if (!searchQuery)
            return buttons.flat().filter(b => !["PreviousPage", "NextPage", "GlobalReturn"].includes(b.buttonText));
        const q = searchQuery.toLowerCase();
        return buttons.flat().filter(b => !["PreviousPage", "NextPage", "GlobalReturn"].includes(b.buttonText) &&
            b.buttonText.toLowerCase().includes(q));
    }
    function rebuildButtonMap() {
        buttonMap = new Map();
        buttons.flat().forEach(button => { buttonMap.set(button.buttonText, button); });
        // Register keyboard key buttons dynamically
        KB_ROWS.forEach(row => {
            for (const ch of row) {
                const key = "SK_" + ch;
                buttonMap.set(key, new ButtonInfo({
                    buttonText: key,
                    isTogglable: false,
                    method: () => {
                        searchQuery += ch;
                        // Rebuild search results in category 20
                        buttons[20] = getSearchResults();
                        currentPage = 0;
                        reloadMenu();
                        sendNotification("Search: " + searchQuery, false);
                    },
                    toolTip: ch
                }));
            }
        });
        // Numbers row
        for (let n = 0; n <= 9; n++) {
            const ch = String(n);
            const key = "SK_" + ch;
            buttonMap.set(key, new ButtonInfo({
                buttonText: key,
                isTogglable: false,
                method: () => {
                    searchQuery += ch;
                    buttons[20] = getSearchResults();
                    currentPage = 0;
                    reloadMenu();
                    sendNotification("Search: " + searchQuery, false);
                },
                toolTip: ch
            }));
        }
        buttonMap.set("SK_back", new ButtonInfo({
            buttonText: "SK_back",
            isTogglable: false,
            method: () => {
                if (searchQuery.length > 0)
                    searchQuery = searchQuery.slice(0, -1);
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search: " + (searchQuery || "(empty)"), false);
            },
            toolTip: "Backspace"
        }));
        buttonMap.set("SK_clear", new ButtonInfo({
            buttonText: "SK_clear",
            isTogglable: false,
            method: () => {
                searchQuery = "";
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search cleared", false);
            },
            toolTip: "Clear search"
        }));
        buttonMap.set("SK_space", new ButtonInfo({
            buttonText: "SK_space",
            isTogglable: false,
            method: () => {
                searchQuery += " ";
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search: " + searchQuery, false);
            },
            toolTip: "Space"
        }));
        buttonMap.set("SK_exit", new ButtonInfo({
            buttonText: "SK_exit",
            isTogglable: false,
            method: () => {
                if (hellOreMode) {
                    if (searchQuery) {
                        spawnHellOreText(searchQuery);
                    }
                    hellOreMode = false;
                    searchActive = false;
                    searchQuery = "";
                    currentCategory = 9;
                    currentPage = 0;
                    reloadMenu();
                    return;
                }
                searchActive = false;
                searchQuery = "";
                currentCategory = 0;
                currentPage = 0;
                reloadMenu();
            },
            toolTip: "Exit search"
        }));
        // Register FAV_ star toggle buttons for every real mod button
        buttons.flat().forEach(btn => {
            if (["PreviousPage", "NextPage", "GlobalReturn", "Search Mods", "Favorites"].includes(btn.buttonText))
                return;
            if (btn.buttonText.startsWith("SK_") || btn.buttonText.startsWith("FAV_"))
                return;
            const favKey = "FAV_" + btn.buttonText;
            buttonMap.set(favKey, new ButtonInfo({
                buttonText: favKey,
                isTogglable: false,
                method: () => {
                    if (favoritedNames.has(btn.buttonText)) {
                        favoritedNames.delete(btn.buttonText);
                        sendNotification("Unfavorited: " + btn.buttonText, false);
                    }
                    else {
                        favoritedNames.add(btn.buttonText);
                        sendNotification("Favorited: " + btn.buttonText, false);
                    }
                    rebuildFavoritesCategory();
                    reloadMenu();
                },
                toolTip: "Toggle favorite:" + btn.buttonText
            }));
        });
    }
    // Category 20: search results — populated dynamically
    buttons[20] = [];
    // Category 21: favorites — populated dynamically
    buttons[21] = [];
    // ===== CATEGORY 23: DOME TRAP GUN MODS =====
    let domeGunActive = false;
    let domeTrapType = "metalball"; // "metalball", "sellingmachine" or "christmaspresent"
    let domeSize = "medium"; // "small", "medium", "large"
    let domeSpinEnabled = false; // Enable spinning animation
    let domeAutoRelease = 0; // 0=off, 5=5sec, 10=10sec, 20=20sec, 30=30sec
    let domeThickness = "normal"; // "normal", "double", "triple"
    let metalBallColor = "silver"; // "silver", "gold", "red", "blue", "green"
    let selectedDomeTarget = null; // Currently selected player to trap
    let domeSpawnedItems = []; // Track spawned items for cleanup
    // Function to get dome radius based on size
    function getDomeRadius(size) {
        switch (size) {
            case "small": return 1.5;
            case "large": return 3.5;
            default: return 2.5; // medium
        }
    }
    // Function to get layer count based on thickness
    function getLayerCount(thickness) {
        switch (thickness) {
            case "double": return 4;
            case "triple": return 5;
            default: return 3; // normal
        }
    }
    // Function to create a dome of items around a player
    function createDomeTrap(targetPlayer, trapType) {
        try {
            if (!targetPlayer || targetPlayer.handle.isNull()) {
                sendNotification("Invalid target!", false);
                return;
            }
            // Show gun pointer line when firing dome
            if (domeGunActive) {
                renderGun();
            }
            const targetPos = getTransform(targetPlayer).method("get_position").invoke();
            const domeRadius = getDomeRadius(domeSize);
            const itemCount = 36; // Number of items to create dome
            const layers = getLayerCount(domeThickness);
            // Determine which prefab to spawn
            let prefabName = "";
            if (trapType === "metalball") {
                prefabName = "item_prefab/item_metal_ball";
            }
            else if (trapType === "christmaspresent") {
                prefabName = "item_prefab/item_christmas_present";
            }
            else {
                prefabName = "item_prefab/item_sellingmachine";
            }
            let spawnedCount = 0;
            const spawnedItems = [];
            // Create multiple layers of items for seamless coverage
            for (let layer = 0; layer < layers; layer++) {
                const layerHeight = (layer - (layers / 2)) * 1.2; // Centered vertical spacing
                // Create a ring of items at this layer
                for (let i = 0; i < itemCount; i++) {
                    const angle = (i / itemCount) * Math.PI * 2;
                    const spinOffset = domeSpinEnabled ? (Date.now() / 5000) * Math.PI * 2 : 0;
                    const finalAngle = angle + spinOffset;
                    const radius = domeRadius + (layer * 0.6);
                    const x = targetPos.fields.x + Math.cos(finalAngle) * radius;
                    const y = targetPos.fields.y + layerHeight + 1.5;
                    const z = targetPos.fields.z + Math.sin(finalAngle) * radius;
                    const spawnPos = [x, y, z];
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, spawnPos, identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                }
            }
            // Add top and bottom caps to seal the dome
            const capLayers = domeThickness === "triple" ? 3 : (domeThickness === "double" ? 2 : 1);
            for (let capLayer = 0; capLayer < capLayers; capLayer++) {
                for (let i = 0; i < 8; i++) {
                    const angle = (i / 8) * Math.PI * 2;
                    const spinOffset = domeSpinEnabled ? (Date.now() / 5000) * Math.PI * 2 : 0;
                    const finalAngle = angle + spinOffset;
                    const capRadius = (domeRadius * (1 - (capLayer * 0.2)));
                    const topX = targetPos.fields.x + Math.cos(finalAngle) * capRadius;
                    const topZ = targetPos.fields.z + Math.sin(finalAngle) * capRadius;
                    // Top cap
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, [topX, targetPos.fields.y + 3.5 + (capLayer * 0.5), topZ], identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                    // Bottom cap
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, [topX, targetPos.fields.y - 0.5 - (capLayer * 0.5), topZ], identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                }
            }
            // Handle auto-release timer
            if (domeAutoRelease > 0) {
                const releaseTime = domeAutoRelease * 1000; // Convert to milliseconds
                scheduleArcaneMainThread(releaseTime, () => {
                    // Try to remove spawned items (if game supports it)
                    for (let i = 0; i < spawnedItems.length; i++) {
                        try {
                            const go = spawnedItems[i].method("get_gameObject").invoke();
                            if (go && !go.isNull?.()) {
                                const destroy = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Object").method("Destroy", 1);
                                destroy.invoke(go);
                            }
                        }
                        catch (e) { }
                    }
                    sendNotification("Dome auto-released!", false);
                }, "dome auto-release");
                sendNotification("Dome will auto-release in " + domeAutoRelease + "s", false);
            }
            const sizeText = domeSize.charAt(0).toUpperCase() + domeSize.slice(1);
            const thicknessText = domeThickness.charAt(0).toUpperCase() + domeThickness.slice(1);
            sendNotification("Dome Created (" + sizeText + "/" + thicknessText + "): " + spawnedCount + " items!", true);
        }
        catch (e) {
            console.error("[Dome Trap] Error:", e);
            sendNotification("Dome trap failed: " + String(e).substring(0, 40), false);
        }
    }
    // ===== CATEGORY 22: TELEPORT MODS =====
    // Define map teleport positions (x, y, z coordinates)
    const mapLocations = {
        "Pirate Island": { x: 0, y: 5, z: 0 },
        "Forest": { x: 100, y: 5, z: 0 },
        "Cave": { x: -100, y: 0, z: 0 },
        "Volcano": { x: 0, y: 10, z: 100 },
        "Beach": { x: 50, y: 0, z: 50 },
        "Arctic": { x: -50, y: 5, z: -50 },
        "Graveyard": { x: -150, y: 2, z: 100 },
        "My Position": { x: 0, y: 0, z: 0 } // Will use current player position
    };
    // Variable to store saved position
    let savedPosition = null;
    // Function to copy player's current position
    function copyPlayerPosition() {
        try {
            const me = NetPlayer.method("get_localPlayer").invoke();
            if (!me || me.handle.isNull()) {
                sendNotification("Could not get your position!", false);
                return;
            }
            const pos = getTransform(me).method("get_position").invoke();
            // Save the Vector3 object directly
            savedPosition = pos;
            // Extract coordinates for display
            const x = pos.fields.x;
            const y = pos.fields.y;
            const z = pos.fields.z;
            sendNotification("Position Saved: (" + Math.round(x) + ", " + Math.round(y) + ", " + Math.round(z) + ")", true);
        }
        catch (e) {
            console.error("[Copy Position] Error:", e);
            sendNotification("Failed to copy position!", false);
        }
    }
    // Function to clear saved position
    function clearSavedPosition() {
        savedPosition = null;
        sendNotification("Saved position cleared!", false);
    }
    // Function to teleport all players to a location
    function teleportAllPlayersToLocation(location) {
        try {
            const me = NetPlayer.method("get_localPlayer").invoke();
            if (!me || me.handle.isNull()) {
                sendNotification("Could not get local player!", false);
                return;
            }
            let targetPos;
            // Special case: use player's current position for "My Position"
            if (location.special === "mypos" || (location.x === 0 && location.y === 0 && location.z === 0 && location.special === "mypos")) {
                targetPos = getTransform(me).method("get_position").invoke();
            }
            else if (location.fields) {
                // If it's already a Vector3 object (from saved position), use it directly
                targetPos = location;
            }
            else {
                // Create a vector for the target position (from map coordinates)
                const Vector3 = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Vector3");
                targetPos = Vector3.alloc();
                targetPos.method(".ctor").overload("System.Single", "System.Single", "System.Single").invoke(location.x, location.y, location.z);
            }
            // Get all players
            const playerDict = NetPlayer.field("playerIDToNetPlayer").value;
            const vals = playerDict.method("get_Values").invoke();
            const en = vals.method("GetEnumerator").invoke();
            let count = 0;
            // Teleport each player
            while (en.method("MoveNext").invoke()) {
                const p = en.method("get_Current").invoke();
                if (!p || p.handle.isNull())
                    continue;
                try {
                    p.method("RPC_Teleport").invoke(targetPos);
                    count++;
                }
                catch (e) {
                    console.error("[Teleport] Failed to teleport player:", e);
                }
            }
            sendNotification("Teleported " + count + " players!", false);
        }
        catch (e) {
            console.error("[Teleport All] Error:", e);
            sendNotification("Teleport Error: " + String(e).substring(0, 50), false);
        }
    }
