    // Anti-kick — CORRECTED MECHANISM (from the dump).
    //
    // The old version hooked NetSessionRPCs.RPC_KickPlayer and dropped EVERY call. That was exactly
    // backwards: RPC_KickPlayer runs on the CALLER (so it blocked YOU from kicking others), and it is
    // NOT the RPC that removes you when someone kicks YOU. A kick actually works like this:
    //   kicker (host / code-owner / dev-menu) -> Nakama API KickUserFromPrivateRoom(targetUserID)
    //     -> Nakama server removes the target from the room and sends the target a notification
    //        with code PrivateRoomKicked (10)  [or Banned (-8) for a room ban]
    //     -> the TARGET's client runs NotificationManager.HandleReceivedNotification(notification),
    //        sees code 10/-8, and disconnects itself.
    // So the only client-side step of a kick that we can intercept is that notification handler.
    // Dropping the kick/ban notification stops our client from voluntarily leaving, while leaving
    // RPC_KickPlayer completely untouched so we can still kick other players normally.
    // (Caveat: this can't stop a purely server-side Photon peer removal; but AC drives the kick
    // through this notification, so in practice this keeps you in the room.)
    let _kickBlockInstalled = false;
    // Members-only bypass — client-side. AC hands the client the room's membersOnly flag + members[]
    // and gates joining locally via NetworkManager.CanJoinRoom_Mobile(). Forcing that true lets you into
    // private codes marked members-only. If a given server also enforces membership server-side this
    // can't beat it (same authority wall as anti-despawn). Toggle-gated, so it's off unless you ask.
    let _membersOnlyBypass = false, _membersOnlyHookInstalled = false;
    function _reclaimMethodHook(method) {
        // A reloaded/duplicated Frida script can leave the same native address replaced by an
        // older thunk.  Revert that thunk before installing this script's closure; otherwise the
        // menu toggles a new JS flag while the old, unreachable closure remains in control.
        try { method.revert(); } catch (_) { }
        try { Interceptor.flush(); } catch (_) { }
    }
    function ensureMembersOnlyBypass() {
        if (_membersOnlyHookInstalled) return;
        try {
            const nm = AssemblyCSharp.class("AnimalCompany.NetworkManager");
            const m = nm && nm.method("CanJoinRoom_Mobile", 0);
            if (m) {
                // Set the guard before touching Interceptor: callbacks can arrive on another game
                // thread while a hook is being installed.
                _membersOnlyHookInstalled = true;
                _reclaimMethodHook(m);
                const originalCanJoin = m.nativeFunction;
                m.implementation = function () {
                    if (_membersOnlyBypass) return true;
                    return !!originalCanJoin(this.handle);
                };
                console.log("[membersbypass] CanJoinRoom gate hook installed (single owner)");
            }
        } catch (e) {
            _membersOnlyHookInstalled = false;
            console.error("[membersbypass] hook:", e);
        }
    }
    function ensureKickBlock() {
        // (1) Primary protection: drop the incoming kick/ban NOTIFICATION so our client refuses to leave.
        if (!_kickBlockInstalled) {
            try {
                const cls = AssemblyCSharp.class("AnimalCompany.NotificationManager");
                const m = cls && cls.method("HandleReceivedNotification", 1);
                if (m) {
                    _kickBlockInstalled = true;
                    _reclaimMethodHook(m);
                    const originalNotificationHandler = m.nativeFunction;
                    m.implementation = function (notification) {
                        try {
                            if (notification && !notification.isNull?.()) {
                                const code = notification.method("get_Code").invoke();
                                if (code === 10 || code === -8) { return; } // PrivateRoomKicked / Banned — drop it, stay in room (no log spam)
                            }
                        } catch (_) { }
                        const notificationPtr = (notification && !notification.isNull?.()) ? notification.handle : NULL;
                        originalNotificationHandler(this.handle, notificationPtr);
                    };
                    console.log("[antikick] kick/ban notification resist installed (single owner)");
                }
            } catch (e) {
                _kickBlockInstalled = false;
                console.error("[antikick] notification hook:", e);
            }
        }
    }
